window.HOEREN_TESTS[19] = {"id":"sprachen-lernen","name":"Sprachen lernen","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Schüler der Sprachschule Aktiv, eine Information für unsere A2-Klasse: Unser Kursraum ändert sich. Statt Raum 102 sind wir ab Montag in Raum 205 — eine Etage höher. Der Lehrer bleibt gleich, nur der Raum ändert sich. Das Klassenzimmer ist größer und heller. Die Zeit bleibt gleich: Montag und Mittwoch von 18 bis 20 Uhr. Vielen Dank!","gender":"f","q":"Was hat sich geändert?","opts":["Die Uhrzeit.","Der Raum.","Der Lehrer."],"correct":1},{"transcript":"Achtung an alle Spanisch-Schüler: Der Kurs am Donnerstag fällt diese Woche aus — die Lehrerin Frau Martinez ist krank. Wir holen die Stunde am nächsten Samstag um 10 Uhr nach. Falls Sie da nicht können, schicken wir Ihnen das Material per E-Mail. Bitte einfach Bescheid sagen.","gender":"m","q":"Wann wird die Stunde nachgeholt?","opts":["Am Samstag um 10 Uhr.","Am Donnerstag wie geplant.","Am Sonntag."],"correct":0},{"transcript":"Hi Tom, hier ist Anna. Ich habe einen super Sprach-Tandem-Partner gefunden — ein Spanier, der Deutsch lernen will und mir Spanisch beibringt. Wir treffen uns einmal pro Woche im Café. Vielleicht hast du auch Lust auf so etwas? Frag mich, ich kann fragen, ob er einen Freund kennt.","gender":"f","q":"Was hat Anna gefunden?","opts":["Einen Sprachkurs.","Eine Sprachreise.","Einen Tandem-Partner."],"correct":2},{"transcript":"Hier ist die Sprachschule Linguafit. Wir bieten ab Mai neue Kurse an. Italienisch für Anfänger startet am 5. Mai, Französisch für Mittelstufe am 8. Mai. Englisch haben wir keinen freien Platz mehr in der A2-Stufe — aber B1 ist noch frei. Anmeldung über die Website bis 30. April.","gender":"f","q":"Welcher Kurs ist voll?","opts":["Italienisch Anfänger.","Englisch A2.","Französisch Mittelstufe."],"correct":1},{"transcript":"Hallo Sara, hier ist Lukas. Hör mal, mein Sprachkurs in Italien — das Programm ist da. Vier Stunden Italienisch täglich am Vormittag, am Nachmittag Ausflüge oder Sport. Auch ein Kochkurs ist dabei — da können wir italienisch kochen lernen. Klingt gut, oder? Ich bin schon ganz aufgeregt.","gender":"m","q":"Was macht man am Nachmittag im Sprachkurs?","opts":["Ausflüge oder Sport.","Mehr Sprachunterricht.","Frei haben."],"correct":0}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer lernt was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Anna","gender":"f","text":"Hallo Lisa! Die Volkshochschule hat neue Sprachkurse ausgeschrieben. Ich habe das Heft hier."},{"speaker":"Lisa","gender":"f","text":"Dann suchen wir etwas Passendes aus. Fünf Leute aus der Familie wollen mitmachen."},{"speaker":"Anna","gender":"f","text":"Ich lerne Spanisch. Der Kurs läuft dienstags immer am späten Abend."},{"speaker":"Lisa","gender":"f","text":"Spanisch klingt lebendig. Ich nehme Italienisch, weil ich das Land liebe."},{"speaker":"Anna","gender":"f","text":"Italienisch passt wirklich gut zu dir. Wolltest du nicht auch Japanisch lernen?"},{"speaker":"Lisa","gender":"f","text":"Nein. Japanisch lerne ich nicht. Die vielen Zeichen sind mir einfach zu fremd."},{"speaker":"Anna","gender":"f","text":"Markus war lange unsicher bei der Wahl."},{"speaker":"Lisa","gender":"f","text":"Markus lernt Französisch. Er möchte im Sommer mit dem Zug nach Paris fahren."},{"speaker":"Anna","gender":"f","text":"Französisch spricht er schon ein wenig. Sara sucht etwas richtig Schweres."},{"speaker":"Lisa","gender":"f","text":"Sara lernt Chinesisch. Die Schrift übt sie jetzt jeden frühen Morgen."},{"speaker":"Anna","gender":"f","text":"Chinesisch ist schwer aber spannend. Ich sah noch Portugiesisch im Heft. Nehmen wir den Kurs?"},{"speaker":"Lisa","gender":"f","text":"Portugiesisch nehmen wir auch nicht. Der Kurs ist schon seit Montag voll."},{"speaker":"Anna","gender":"f","text":"Lukas hat seine Sprache auch schon gewählt."},{"speaker":"Lisa","gender":"f","text":"Lukas lernt Russisch. Seine Großmutter spricht es seit Jahren zu Hause."},{"speaker":"Anna","gender":"f","text":"Einverstanden. Ich melde uns morgen früh am Computer an. Bis zum ersten Kursabend."}],"options":[{"letter":"a","text":"Portugiesisch"},{"letter":"b","text":"Chinesisch"},{"letter":"c","text":"Japanisch"},{"letter":"d","text":"Russisch"},{"letter":"e","text":"Englisch"},{"letter":"f","text":"Italienisch"},{"letter":"g","text":"Arabisch"},{"letter":"h","text":"Spanisch"},{"letter":"i","text":"Französisch"}],"items":[{"person":"Anna","correct":"h"},{"person":"Lisa","correct":"f"},{"person":"Markus","correct":"i"},{"person":"Sara","correct":"b"},{"person":"Lukas","correct":"d"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Sekretärin","gender":"f","text":"Guten Tag, welche Sprache möchten Sie lernen?"},{"speaker":"Kundin","gender":"f","text":"Ich überlege zwischen Spanisch und Italienisch. Beide auf einmal ist mir zu viel."},{"speaker":"Sekretärin","gender":"f","text":"Wozu brauchen Sie es — Familie oder Urlaub?"},{"speaker":"Kundin","gender":"f","text":"Mein Mann ist aus Spanien. Aber wir reisen oft nach Italien."},{"speaker":"Sekretärin","gender":"f","text":"Dann ist Spanisch wichtiger für die Familie. Italienisch können Sie später."},{"speaker":"Kundin","gender":"f","text":"Stimmt, ich melde mich für Spanisch an, nicht für Italienisch und nicht für beide."}],"q":"Welche Sprache wird die Kundin lernen?","opts":["Beide.","Italienisch.","Spanisch."],"correct":2},{"lines":[{"speaker":"Lehrer","gender":"m","text":"Na, wie war deine Spanisch-Hausaufgabe? Vokabeln, Verben, Aussprache?"},{"speaker":"Schülerin","gender":"f","text":"Schwer, ich habe besonders mit den Verben Probleme — die Konjugation. Die Aussprache geht."},{"speaker":"Lehrer","gender":"m","text":"Üben wir das jetzt zusammen. Vokabeln kannst du gut, das habe ich gesehen. Die Aussprache auch."},{"speaker":"Schülerin","gender":"f","text":"Ja, Vokabeln sind okay. Aber Grammatik, vor allem die Verb-Konjugation, ist schwer."},{"speaker":"Lehrer","gender":"m","text":"Gut, dann üben wir heute nur die Verben. Das wird besser."}],"q":"Was findet die Schülerin schwer?","opts":["Vokabeln.","Aussprache.","Verb-Konjugation."],"correct":2},{"lines":[{"speaker":"Mitarbeiterin","gender":"f","text":"Guten Tag, möchten Sie an einer Sprachreise teilnehmen? Italien, Spanien oder Frankreich?"},{"speaker":"Kunde","gender":"m","text":"Ja, was bieten Sie an, und was kostet es?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Eine Woche Italien 950 Euro, zwei Wochen Spanien 1800. Auch eine Woche Frankreich für 1200 Euro."},{"speaker":"Kunde","gender":"m","text":"Spanien ist zu teuer, Frankreich auch. Italien ist im Budget. Das nehme ich."},{"speaker":"Mitarbeiterin","gender":"f","text":"Gerne, dann Italien für 950 Euro. Ich schicke Ihnen die Unterlagen."}],"q":"Welche Reise wählt der Kunde?","opts":["Spanien für 1800 Euro.","Italien für 950 Euro.","Frankreich für 1200 Euro."],"correct":1},{"lines":[{"speaker":"Mutter","gender":"f","text":"Lukas, du musst Englisch üben für den Test morgen."},{"speaker":"Sohn","gender":"m","text":"Ich habe schon eine Stunde gelernt!"},{"speaker":"Mutter","gender":"f","text":"Wirklich? Aber ich habe dich am Computer spielen sehen."},{"speaker":"Sohn","gender":"m","text":"Das war nach dem Lernen. Wirklich. Ich habe Vokabeln gelernt."},{"speaker":"Mutter","gender":"f","text":"Okay, ich glaube dir. Aber jetzt noch eine halbe Stunde Grammatik."}],"q":"Was soll Lukas jetzt noch machen?","opts":["Eine halbe Stunde Grammatik.","Spielen.","Schlafen gehen."],"correct":0},{"lines":[{"speaker":"Kollege","gender":"m","text":"Du sprichst so gut Französisch! Wie hast du das gelernt — Kurse, Bücher, oder im Land?"},{"speaker":"Kollegin","gender":"f","text":"Ich habe in Frankreich gelebt — drei Jahre lang. Vor allem durch das Leben dort."},{"speaker":"Kollege","gender":"m","text":"Hast du auch viele Sprachkurse gemacht, oder nur Bücher gelesen?"},{"speaker":"Kollegin","gender":"f","text":"Nur am Anfang einen Crashkurs, nicht viele Kurse. Nur durch Bücher habe ich es nicht gelernt."},{"speaker":"Kollege","gender":"m","text":"Also vor allem durch das Leben in Frankreich. Respekt!"}],"q":"Wie hat die Kollegin Französisch gelernt?","opts":["Vor allem durch Leben in Frankreich.","In vielen Sprachkursen.","Nur durch Bücher."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Garcia, einer Spanisch-Lehrerin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Garcia, Sie unterrichten Spanisch in Deutschland seit 14 Jahren. Wie sind Sie hierhergekommen?"},{"speaker":"Garcia","gender":"f","text":"Ich bin in Madrid geboren. Mit 25 habe ich einen Deutschen kennengelernt und bin nach München gezogen. Erst habe ich als Übersetzerin gearbeitet, aber das Unterrichten gefällt mir mehr. Der direkte Kontakt mit Schülern ist schöner."},{"speaker":"Reporter","gender":"m","text":"Was ist das Schwierigste für Deutsche, die Spanisch lernen?"},{"speaker":"Garcia","gender":"f","text":"Die Konjugation der Verben! Spanisch hat viele Zeiten, mehr als Deutsch. Auch ‚ser‘ und ‚estar‘ — beide heißen ‚sein‘ aber haben andere Bedeutungen. Das verwirrt am Anfang."},{"speaker":"Reporter","gender":"m","text":"Was lieben Ihre Schüler an Spanisch?"},{"speaker":"Garcia","gender":"f","text":"Die Klänge — Spanisch ist eine sehr musikalische Sprache. Auch die Kultur — Tapas, Flamenco, das macht Lust auf das Lernen. Aussprache ist nicht schwer, das ist ein Vorteil gegenüber Englisch oder Französisch."},{"speaker":"Reporter","gender":"m","text":"Reisen Sie noch oft nach Spanien?"},{"speaker":"Garcia","gender":"f","text":"Jedes Jahr im Sommer — drei Wochen bei meiner Familie. Meine Eltern und Geschwister leben noch in Madrid. Manchmal bringe ich Schüler mit auf eine Sprachreise — das macht großen Spaß."},{"speaker":"Reporter","gender":"m","text":"Und welche Sprache möchten Sie noch lernen?"},{"speaker":"Garcia","gender":"f","text":"Italienisch! Ich verstehe es schon halb, weil es Spanisch ähnlich ist. Aber gesprochen ist es schwieriger. Vielleicht bald nehme ich einen Kurs."}],"items":[{"q":"Spanisch hat weniger Zeiten als Deutsch.","correct":"nein"},{"q":"Frau Garcia arbeitete zuerst als Übersetzerin in Deutschland.","correct":"ja"},{"q":"Die Aussprache ist für deutsche Schüler einfach.","correct":"ja"},{"q":"Sie besucht jedes Jahr ihre Familie in Madrid.","correct":"ja"},{"q":"Sie spricht schon perfekt Italienisch.","correct":"nein"}]}]};
